    // Constructor using an initializer list
    FArray1D(std::initializer_list<T> values, size_t ni, int start_i = 1)
        : ni(ni), start_i(start_i), data(new T[ni]), ownsData(true) {
        size_t idx = 0;
        for (T value : values) {
            if (idx < ni) {
                data[idx++] = value;
            }
        }
