namespace {
// Equivalent of Fortran's trim(): strip trailing blanks.
std::string ftrim(const std::string& s) {
  std::size_t end = s.find_last_not_of(' ');
  return (end == std::string::npos) ? std::string() : s.substr(0, end + 1);
}
}  // namespace

void ggZZcapture(const std::string& label, int h34, int h56,
                  int j1, int j2, int j3, int j4, int j5, int j6,
                  std::complex<double>& amp0, std::complex<double>& amp2,
                  std::complex<double>& amp4) {
  const int imt0 = 1, imt2 = 2, imt4 = 3;
  const int ipp = 1, imp = 2;
  int htag, ltag = 0, itag = 0;

  if (first) {
    for (std::size_t idx = 0; idx < res.ni * res.nj * res.nk * res.nl; ++idx) {
      res.data[idx] = czip;
    }
    first = false;
  }

  htag = -1;

  std::string trimmed = ftrim(label);

  // --- Canonical permutation:  1 2 3 4 5 6
  if ((j1 == 1) && (j2 == 2) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
    if ((trimmed == "1x2") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_2;
    }
    if ((trimmed == "1x2pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_2;
    }
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_34;
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_34;
    }
    if ((trimmed == "12x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c12_34;
    }
    if ((trimmed == "12x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c12_34;
    }
    if ((trimmed == "1x34x2mp") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d1_34_2;
    }
    if ((trimmed == "1x34x2pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d1_34_2;
    }
    if ((trimmed == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d2_1_34;
    }
    if ((trimmed == "2x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d2_1_34;
    }
    if ((trimmed == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d6_2_1_34;
    }
    if ((label.substr(0, 5) == "bubmp") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 2;
      itag = label[5] - '0';
    }
    if ((label.substr(0, 5) == "bubpp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 2;
      itag = label[5] - '0';
    }
  }

  // --- Permute 1 and 2:  2 1 3 4 5 6
  if ((j1 == 2) && (j2 == 1) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "2x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d1_2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d6_1_2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
  }

  // --- Permute 3,4 and 5,6:  1 2 5 6 3 4
  if ((j1 == 1) && (j2 == 2) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_56;
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_56;
    }
    if ((trimmed == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d1_2_34;
    }
  }

  // --- Permute 1,3,4 and 2,5,6:  2 1 3 4 5 6
  if ((j1 == 2) && (j2 == 1) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c2_56;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c2_56;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
  }

  if (htag < 0) {
    return;
  }

  // --- assign results
  res(htag, ltag, itag, imt0) = amp0;  // @coverage-probe
  res(htag, ltag, itag, imt2) = amp2;
  res(htag, ltag, itag, imt4) = amp4;

  if (std::abs(res(htag, ltag, itag, imt0)) < 1e-8) res(htag, ltag, itag, imt0) = czip;
  if (std::abs(res(htag, ltag, itag, imt2)) < 1e-8) res(htag, ltag, itag, imt2) = czip;
  if (std::abs(res(htag, ltag, itag, imt4)) < 1e-8) res(htag, ltag, itag, imt4) = czip;

  return;
}

extern "C" {
